def interleave(a, b):
    a, b = list(a), list(b)
    out = []
    for i in range(max(len(a), len(b))):
        if i < len(a):
            out.append(a[i])
        if i < len(b):
            out.append(b[i])
    return out

def dedupe_adjacent(seq):
    out = []
    for x in seq:
        if not out or out[-1] != x:
            out.append(x)
    return out

def longest_run(seq):
    best = run = 0
    prev = None
    for x in seq:
        if run and x == prev:
            run += 1
        else:
            run = 1
        prev = x
        best = max(best, run)
    return best

def sliding_max(nums, k):
    nums = list(nums)
    if not isinstance(k, int) or k <= 0 or k > len(nums):
        raise ValueError(k)
    return [max(nums[i:i + k]) for i in range(len(nums) - k + 1)]

def partition(nums, threshold):
    low, high = [], []
    for x in nums:
        (low if x < threshold else high).append(x)
    return low, high

def flatten_depth(seq, depth):
    if not isinstance(depth, int) or depth < 0:
        raise ValueError(depth)
    out = []
    for x in seq:
        if depth > 0 and isinstance(x, (list, tuple)):
            out.extend(flatten_depth(x, depth - 1))
        else:
            out.append(x)
    return out

def remove_dupes_keep_last(seq):
    seq = list(seq)
    seen = set()
    out = []
    for x in reversed(seq):
        if x not in seen:
            seen.add(x)
            out.append(x)
    return list(reversed(out))

def paired_diffs(nums):
    nums = list(nums)
    return [nums[i] - nums[i - 1] for i in range(1, len(nums))]

def chunk_by_sign(nums):
    def kind(x):
        return -1 if x < 0 else (1 if x > 0 else 0)
    out = []
    for x in nums:
        if out and kind(out[-1][0]) == kind(x):
            out[-1].append(x)
        else:
            out.append([x])
    return out

def running_max(nums):
    out, best = [], None
    for x in nums:
        best = x if best is None else max(best, x)
        out.append(best)
    return out
